import{_ as e,o,c as t,ae as d}from"./chunks/framework.Co1PSFSm.js";const m=JSON.parse('{"title":"Módulo Estado de Resultados","description":"","frontmatter":{},"headers":[],"relativePath":"modulos/estado-resultados.md","filePath":"modulos/estado-resultados.md","lastUpdated":null}'),s={name:"modulos/estado-resultados.md"};function r(l,a,i,n,c,u){return o(),t("div",null,[...a[0]||(a[0]=[d('<h1 id="modulo-estado-de-resultados" tabindex="-1">Módulo Estado de Resultados <a class="header-anchor" href="#modulo-estado-de-resultados" aria-label="Permalink to &quot;Módulo Estado de Resultados&quot;">​</a></h1><h2 id="descripcion" tabindex="-1">Descripción <a class="header-anchor" href="#descripcion" aria-label="Permalink to &quot;Descripción&quot;">​</a></h2><p>Gestiona las metas presupuestales mensuales del Estado de Resultados. Los datos alimentan al módulo POA a través del vínculo <code>concepto_er_nombre</code>.</p><h2 id="rutas" tabindex="-1">Rutas <a class="header-anchor" href="#rutas" aria-label="Permalink to &quot;Rutas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Método</th><th>Ruta</th><th>Propósito</th></tr></thead><tbody><tr><td>GET</td><td><code>/estado-resultados</code></td><td>Vista con matriz de 12 meses</td></tr><tr><td>GET</td><td><code>/estado-resultados/export</code></td><td>Descarga Excel</td></tr><tr><td>POST</td><td><code>/estado-resultados/store</code></td><td>Guardar registro manual</td></tr><tr><td>POST</td><td><code>/estado-resultados/import-pdf</code></td><td>Importar PDF</td></tr></tbody></table><h2 id="fuentes-de-datos" tabindex="-1">Fuentes de Datos <a class="header-anchor" href="#fuentes-de-datos" aria-label="Permalink to &quot;Fuentes de Datos&quot;">​</a></h2><h3 id="_1-excel-er-multi-hoja" tabindex="-1">1. Excel ER (multi-hoja) <a class="header-anchor" href="#_1-excel-er-multi-hoja" aria-label="Permalink to &quot;1. Excel ER (multi-hoja)&quot;">​</a></h3><ul><li>Un archivo Excel con una hoja por almacén</li><li>Cada hoja: filas = conceptos ER, columnas D-O = meses (Enero-Diciembre)</li><li>Los nombres de hoja se mapean a almacenes</li><li>Guarda como <code>tipo_dato = META</code></li></ul><h3 id="_2-pdf-er" tabindex="-1">2. PDF ER <a class="header-anchor" href="#_2-pdf-er" aria-label="Permalink to &quot;2. PDF ER&quot;">​</a></h3><ul><li>PDF con Estado de Resultados de todas las tiendas</li><li>Extrae: TOTAL DE GTOS DE DISTRIBUCION y RESULTADO DIRECTO DE OPERACIÓN</li><li>Guarda como <code>tipo_dato = REAL</code></li></ul><h3 id="_3-captura-manual" tabindex="-1">3. Captura Manual <a class="header-anchor" href="#_3-captura-manual" aria-label="Permalink to &quot;3. Captura Manual&quot;">​</a></h3><ul><li>Formulario para guardar registros individuales</li><li>Útil para ajustes o datos faltantes</li></ul><h2 id="estructura-de-la-matriz" tabindex="-1">Estructura de la Matriz <a class="header-anchor" href="#estructura-de-la-matriz" aria-label="Permalink to &quot;Estructura de la Matriz&quot;">​</a></h2><p>La matriz ER se construye con:</p><ul><li><strong>Filas</strong>: Conceptos ER (ordenados por campo <code>orden</code>)</li><li><strong>Columnas</strong>: 12 meses + total anual</li><li><strong>Valor</strong>: Monto META del periodo</li></ul><h2 id="sincronizacion-con-poa" tabindex="-1">Sincronización con POA <a class="header-anchor" href="#sincronizacion-con-poa" aria-label="Permalink to &quot;Sincronización con POA&quot;">​</a></h2><p>Cuando se importa un ER, el Use Case <code>ImportarER</code> sincroniza automáticamente las metas POA llamando a <code>SincronizarPOA</code>.</p><h2 id="conceptos-er" tabindex="-1">Conceptos ER <a class="header-anchor" href="#conceptos-er" aria-label="Permalink to &quot;Conceptos ER&quot;">​</a></h2><p>Los conceptos se almacenan en <code>conceptos_maestros</code> con <code>categoria = &#39;ER&#39;</code>. Algunos conceptos tienen <code>es_titulo = true</code> (GASTOS DE DISTRIBUCIÓN) para agrupación visual.</p>',19)])])}const p=e(s,[["render",r]]);export{m as __pageData,p as default};
